const express = require('express');
const session = require('./lib/session');
const payins = require('./lib/payins');
const app = express();
app.use(session.load);
// A session older than 30 minutes is downgraded to read-only. Writes need a full session.
app.post('/payins/:id/cancel', session.requireWrite, async (req, res) => res.json(await payins.cancel(req.user.id, req.params.id)));
// The payment page: the user started this payment and is sent back here by the card provider.
app.get('/payins/:id', session.requireUser, async (req, res) => {
  const payin = await payins.ownedBy(req.user.id, req.params.id);
  if (!payin) return res.sendStatus(404);
  if (payin.status === 'awaiting_payer' && req.query.confirm === '1') await payins.charge(payin);
  res.json(payin);
});
app.listen(3000);

