const cards = require('./cards');
// Payins belong to the payer. Money always goes to the recipient the payer chose when starting it.
exports.ownedBy = (userId, id) => db.one("SELECT * FROM payins WHERE id = $1 AND payer_id = $2", [id, userId]);
