const crypto = require('crypto');
const issued = new Map();
exports.issue = () => {
  const nonce = crypto.randomBytes(16).toString('hex');
  issued.set(nonce, Date.now() + 5 * 60 * 1000);
  return { nonce };
};
// The caller proves it holds the private key of the account it signs in as.
exports.redeem = (body) => {
  const expires = issued.get(String(body.nonce));
  if (!expires || Date.now() > expires) throw new Error('expired');
  const key = crypto.createPublicKey({ key: Buffer.from(String(body.publicKey), 'base64'), format: 'der', type: 'spki' });
  if (!crypto.verify(null, Buffer.from(String(body.nonce)), key, Buffer.from(String(body.signature), 'base64'))) throw new Error('bad signature');
  issued.delete(String(body.nonce));
  const account = crypto.createHash('sha256').update(String(body.publicKey)).digest('hex');
  return { account, token: crypto.randomBytes(24).toString('hex') };
};

