package serve

import (
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"os"
	"strings"

	"example.com/disburse/internal/serve/middleware"
)

func Routes() http.Handler {
	mux := http.NewServeMux()
	mux.Handle("/disbursements", middleware.APIKeyAuth(lookupKey, http.HandlerFunc(createDisbursement)))
	return RateLimit(mux)
}

// One partner key, stored as a hash, allowed only from the partner's servers.
func lookupKey(token string) (middleware.APIKey, bool) {
	sum := sha256.Sum256([]byte(token))
	want := os.Getenv("PARTNER_KEY_SHA256")
	if want == "" || hex.EncodeToString(sum[:]) != want {
		return middleware.APIKey{}, false
	}
	return middleware.APIKey{Hash: want, AllowedIPs: strings.Split(os.Getenv("PARTNER_ALLOWED_IPS"), ",")}, true
}

// Sends money from the platform wallet to the receivers in the request.
func createDisbursement(w http.ResponseWriter, r *http.Request) { w.WriteHeader(http.StatusCreated) }

