package middleware

import (
	"net"
	"net/http"
	"strings"
)

// An API key can be limited to a list of IP addresses. The list protects a
// key that leaks: it only works from the owner's servers.
type APIKey struct {
	Hash       string
	AllowedIPs []string
}

func (k APIKey) IsAllowedIP(ip string) bool {
	if len(k.AllowedIPs) == 0 {
		return true
	}
	for _, a := range k.AllowedIPs {
		if a == ip {
			return true
		}
	}
	return false
}

func clientIP(r *http.Request) string {
	for _, h := range []string{"X-Forwarded-For", "X-Real-IP"} {
		if v := r.Header.Get(h); v != "" {
			return strings.TrimSpace(strings.Split(v, ",")[0])
		}
	}
	host, _, _ := net.SplitHostPort(r.RemoteAddr)
	return host
}

func APIKeyAuth(lookup func(string) (APIKey, bool), next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key, ok := lookup(strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer "))
		if !ok || !key.IsAllowedIP(clientIP(r)) {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		next.ServeHTTP(w, r)
	})
}

